import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { Bike, Truck, Shovel as van, Milestone } from 'lucide-react'; // Premium Icons
import './BookingForm.css';

const BookingForm = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        senderName: '',
        senderPhone: '',
        sourceAddress: '',
        destinationAddress: '',
        vehicleType: 'bike',
        weight: '',
        distanceKm: ''
    });

    const vehicleOptions = [
        {
            id: 'bike',
            label: 'Two-Wheeler',
            desc: 'Quick & Small (Up to 20kg)',
            icon: <Bike size={32} strokeWidth={1.5} />
        },
        {
            id: 'tata ace',
            label: 'Tata Ace',
            desc: 'Heavy Loads (700kg)',
            icon: <Truck size={32} strokeWidth={1.5} />
        },
        {
            id: 'pickup 8ft',
            label: 'Pickup 8ft',
            desc: 'Large Items (1.5 Tonne)',
            icon: <Milestone size={32} strokeWidth={1.5} />
        }
    ];

    const handleChange = (e) => {
        const { name, value } = e.target;
        const finalValue = (name === 'weight' || name === 'distanceKm') ? parseFloat(value) : value;
        setFormData({ ...formData, [name]: finalValue });
    };

    const handleVehicleSelect = (id) => {
        setFormData({ ...formData, vehicleType: id });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            const res = await axios.post("http://localhost:9023/api/parcels/book", formData);
            if (res.data && res.data.trackingId) {
                alert(`Booking Successful! ID: ${res.data.trackingId}`);
                navigate('/track'); 
            }
        } catch (error) {
            console.error(error);
            alert("Booking failed!");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="booking-container">
            <div className="booking-card-main">
                <div className="header-section">
                    <h2>🚀 Book Your Parcel</h2>
                    <p>Enter details to get instant pricing</p>
                </div>
                
                <form onSubmit={handleSubmit}>
                    <div className="form-row">
                        <input type="text" name="senderName" placeholder="Full Name" onChange={handleChange} required />
                        <input type="text" name="senderPhone" placeholder="Phone Number" onChange={handleChange} required />
                    </div>

                    <input type="text" name="sourceAddress" placeholder="Pickup Address (From)" onChange={handleChange} required />
                    <input type="text" name="destinationAddress" placeholder="Drop Address (To)" onChange={handleChange} required />
                    
                    <label className="section-label">Choose Your Vehicle</label>
                    <div className="vehicle-grid">
                        {vehicleOptions.map((vehicle) => (
                            <div 
                                key={vehicle.id}
                                className={`vehicle-item ${formData.vehicleType === vehicle.id ? 'active' : ''}`}
                                onClick={() => handleVehicleSelect(vehicle.id)}
                            >
                                <div className="vehicle-icon-wrapper">
                                    {vehicle.icon}
                                </div>
                                <div className="vehicle-info">
                                    <span className="v-title">{vehicle.label}</span>
                                    <span className="v-desc">{vehicle.desc}</span>
                                </div>
                                {formData.vehicleType === vehicle.id && <div className="selected-dot"></div>}
                            </div>
                        ))}
                    </div>

                    <div className="form-row">
                        <div className="input-with-label">
                            <label>Distance (km)</label>
                            <input type="number" name="distanceKm" placeholder="0" onChange={handleChange} required />
                        </div>
                        <div className="input-with-label">
                            <label>Weight (kg)</label>
                            <input type="number" name="weight" placeholder="0" onChange={handleChange} required />
                        </div>
                    </div>

                    <button type="submit" className="book-btn" disabled={loading}>
                        {loading ? 'Calculating...' : 'Confirm Booking'}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default BookingForm;
